window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dd1c0f3897486249"]={"versions": [{"id": "FIG-dd1c0f3897486249", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Header- und Bit-/Byte-Layout-Diagramm für den Header des End-to-End-Schutzprofils (E2E Profile 44) gemäß AUTOSAR PRS E2E-Protokoll. Das Diagramm spezifiziert die Serialisierungsstruktur der Kontrollfelder innerhalb der Kommunikationsnachricht für AUTOSAR Classic und Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte Header-Felder auf Byte- und Bitebene über eine Breite von 32 Bit (Transmission order Bit 0 bis 31) und eine Gesamtlänge von 12 Byte (Byte-Offsets 0, 4 und 8):</p>\n<ul class=\"fig-list\"><li>Byte 0–1 (Bit 0–15): <code>E2E Length</code> (16 Bit)\n</li><li>Byte 2–3 (Bit 16–31): <code>E2E Counter</code> (16 Bit)\n</li><li>Byte 4–7 (Bit 0–31): <code>E2E Data ID</code> (32 Bit)\n</li><li>Byte 8–11 (Bit 0–31): <code>E2E CRC</code> (32 Bit)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenfeldbelegung bei der Übertragung. Die Senderseite ermittelt die Nutzdatenlänge für <code>E2E Length</code>, inkrementiert den <code>E2E Counter</code>, fügt die konfigurierte <code>E2E Data ID</code> ein und berechnet die 32-Bit-Prüfsumme <code>E2E CRC</code> über die geschützten Anteile. Die Übertragungsreihenfolge folgt der dargestellten Byte- und Bitanordnung (Transmission order von Bit 0 bis 31 je 32-Bit-Wort). Auf der Empfängerseite werden die Felder in derselben Reihenfolge ausgelesen und validiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Feldlayout für Implementierungen von E2E Profile 44. Die exakte Bitbreite, Reihenfolge und Byte-Offset-Positionierung von <code>E2E Length</code> (16 Bit), <code>E2E Counter</code> (16 Bit), <code>E2E Data ID</code> (32 Bit) und <code>E2E CRC</code> (32 Bit) müssen zwingend eingehalten werden, um Protokollkonformität und Interoperabilität zwischen E2E-Sender und E2E-Empfänger sicherzustellen.</p>"}, {"id": "FIG-1355f85a0a8d6d10", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Header- und Bit-/Byte-Layout-Diagramm für den Header des End-to-End-Schutzprofils (E2E Profile 44) gemäß AUTOSAR PRS E2E-Protokoll. Das Diagramm spezifiziert die Serialisierungsstruktur der Kontrollfelder innerhalb der Kommunikationsnachricht für AUTOSAR Classic und Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturierte Header-Felder auf Byte- und Bitebene über eine Breite von 32 Bit (Transmission order Bit 0 bis 31) und eine Gesamtlänge von 12 Byte (Byte-Offsets 0, 4 und 8):</p>\n<ul class=\"fig-list\"><li>Byte 0–1 (Bit 0–15): <code>E2E Length</code> (16 Bit)\n</li><li>Byte 2–3 (Bit 16–31): <code>E2E Counter</code> (16 Bit)\n</li><li>Byte 4–7 (Bit 0–31): <code>E2E Data ID</code> (32 Bit)\n</li><li>Byte 8–11 (Bit 0–31): <code>E2E CRC</code> (32 Bit)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenfeldbelegung bei der Übertragung. Die Senderseite ermittelt die Nutzdatenlänge für <code>E2E Length</code>, inkrementiert den <code>E2E Counter</code>, fügt die konfigurierte <code>E2E Data ID</code> ein und berechnet die 32-Bit-Prüfsumme <code>E2E CRC</code> über die geschützten Anteile. Die Übertragungsreihenfolge folgt der dargestellten Byte- und Bitanordnung (Transmission order von Bit 0 bis 31 je 32-Bit-Wort). Auf der Empfängerseite werden die Felder in derselben Reihenfolge ausgelesen und validiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Feldlayout für Implementierungen von E2E Profile 44. Die exakte Bitbreite, Reihenfolge und Byte-Offset-Positionierung von <code>E2E Length</code> (16 Bit), <code>E2E Counter</code> (16 Bit), <code>E2E Data ID</code> (32 Bit) und <code>E2E CRC</code> (32 Bit) müssen zwingend eingehalten werden, um Protokollkonformität und Interoperabilität zwischen E2E-Sender und E2E-Empfänger sicherzustellen.</p>"}], "trans": [{"from": "FIG-dd1c0f3897486249", "to": "FIG-1355f85a0a8d6d10", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
